"""Sartiq Studio, a cinematic Gradio demo for fashion image generation.

The expensive generation pipeline is intentionally disconnected in this build.
The first uploaded reference is echoed as the result so the complete experience
can be tested without generation costs.
"""
from __future__ import annotations

import os
import tempfile
import time
from pathlib import Path

import gradio as gr
import numpy as np
from PIL import Image, ImageOps

NO_INPUT_STATUS = "Add at least one garment photo first."


def collect_photos(gallery: list[str | tuple[str, str | None]] | None) -> list[Path]:
    """Collect garment photos uploaded from local storage."""
    photos: list[Path] = []
    for item in gallery or []:
        path = item[0] if isinstance(item, (tuple, list)) else item
        if isinstance(path, str) and path:
            photos.append(Path(path))
    return photos


def load_image(path: Path) -> np.ndarray:
    with Image.open(path) as image:
        return np.asarray(ImageOps.exif_transpose(image).convert("RGB"))


def enhance(
    gallery: list[str | tuple[str, str | None]] | None,
) -> tuple[tuple[np.ndarray, np.ndarray] | None, str | None]:
    """Echo the first reference while the production pipeline is disconnected."""
    photos = collect_photos(gallery)
    if not photos:
        return None, None

    started = time.perf_counter()
    source = load_image(photos[0])

    # Replace this line with the real generated image when reconnecting the model.
    generated = source.copy()

    with tempfile.NamedTemporaryFile(
        prefix="sartiq-studio-", suffix=".png", delete=False
    ) as handle:
        Image.fromarray(generated).save(handle.name, format="PNG")
        download_path = handle.name

    return (source, generated), download_path


def reset() -> tuple[object, ...]:
    return None, None, None


