HEAD = """
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<meta name="theme-color" content="#f5f5f7">
<script>
(() => {
  const boot = () => {
    const canvas = document.getElementById('ambient-dot-grid');
    if (!canvas || canvas.dataset.ready) return;
    canvas.dataset.ready = '1';
    const ctx = canvas.getContext('2d');
    const mouse = {x:-9999,y:-9999};
    let dpr=1,w=0,h=0,raf=0;
    const resize=()=>{dpr=Math.min(devicePixelRatio||1,2);w=innerWidth;h=innerHeight;canvas.width=w*dpr;canvas.height=h*dpr;canvas.style.width=w+'px';canvas.style.height=h+'px';ctx.setTransform(dpr,0,0,dpr,0,0);};
    const draw=()=>{ctx.clearRect(0,0,w,h);const gap=30,radius=310;for(let y=15;y<h;y+=gap){for(let x=15;x<w;x+=gap){const dist=Math.hypot(x-mouse.x,y-mouse.y);const proximity=Math.max(0,1-dist/radius);const glow=proximity*proximity*(3-2*proximity);ctx.beginPath();ctx.arc(x,y,1.02+glow*1.18,0,Math.PI*2);ctx.fillStyle=glow>0?`rgba(241,99,133,${.25+glow*.63})`:'rgba(29,29,31,.27)';ctx.fill();}}raf=requestAnimationFrame(draw);};
    addEventListener('resize',resize,{passive:true});addEventListener('pointermove',e=>{mouse.x=e.clientX;mouse.y=e.clientY},{passive:true});addEventListener('pointerleave',()=>{mouse.x=-9999;mouse.y=-9999});resize();draw();
  };
  new MutationObserver(boot).observe(document.documentElement,{childList:true,subtree:true});
  document.addEventListener('DOMContentLoaded',boot);setTimeout(boot,250);
})();
</script>
<script>
(() => {
  const bootReveal = () => {
    const section = document.getElementById('reveal-collage');
    if (!section || section.dataset.parallaxReady) return;
    section.dataset.parallaxReady = '1';
    const shots = [...section.querySelectorAll('.sq-reveal-shot')];
    const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;
    let visible = false, ticking = false;
    const render = () => {
      ticking = false;
      if (!visible || reduced) return;
      const rect = section.getBoundingClientRect();
      const progress = Math.max(0, Math.min(1, (innerHeight - rect.top) / (innerHeight + rect.height)));
      shots.forEach((shot) => {
        const speed = Number(shot.dataset.speed || 1);
        const offset = (1 - progress) * 185 * speed - progress * 110 * speed;
        shot.style.setProperty('--travel', `${offset.toFixed(2)}px`);
      });
    };
    const requestRender = () => { if (!ticking) { ticking = true; requestAnimationFrame(render); } };
    new IntersectionObserver(([entry]) => { visible = entry.isIntersecting; if (visible) requestRender(); }, {rootMargin: '20% 0px'}).observe(section);
    addEventListener('scroll', requestRender, {passive: true});
    addEventListener('resize', requestRender, {passive: true});
    if (reduced) shots.forEach((shot) => shot.style.setProperty('--travel', '0px'));
  };
  new MutationObserver(bootReveal).observe(document.documentElement, {childList: true, subtree: true});
  document.addEventListener('DOMContentLoaded', bootReveal);
  setTimeout(bootReveal, 300);
})();
</script>
"""

