LAYOUT_JS = r"""
(gallery) => {
  const shell = document.getElementById("studio-shell");
  if (!shell) return gallery;
  const hasImages = Array.isArray(gallery) && gallery.length > 0;
  shell.classList.toggle("is-expanded", hasImages);
  return gallery;
}
"""

RESET_LAYOUT_JS = r"""
() => {
  document.getElementById("studio-shell")?.classList.remove("is-expanded");
}
"""

GENERATE_JS = r"""
(gallery) => {
  const hasGallery = Array.isArray(gallery) && gallery.length > 0;
  if (!hasGallery) return gallery;

  const phrases = [
    "Reading the silhouette.",
    "Preserving every detail.",
    "Building the light.",
    "Creating your studio image."
  ];

  let overlay = document.getElementById("sartiq-generating");
  if (!overlay) {
    overlay = document.createElement("div");
    overlay.id = "sartiq-generating";
    overlay.style.cssText = `position:fixed;inset:0;z-index:9999;background:#000;color:#fff;
      display:grid;place-items:center;text-align:center;padding:28px;opacity:0;transition:opacity .35s ease`;
    overlay.innerHTML = `<div><div id="sartiq-phrase" style="font-family:-apple-system,BlinkMacSystemFont,'Helvetica Neue',sans-serif;
      font-size:clamp(40px,7vw,96px);line-height:.95;letter-spacing:-.06em;font-weight:650"></div>
      <div style="width:52px;height:2px;background:#333;margin:34px auto 0;overflow:hidden">
      <div style="width:100%;height:100%;background:#fff;animation:sartiq-load 3.7s linear both"></div></div></div>`;
    const style = document.createElement("style");
    style.textContent = `@keyframes sartiq-load{from{transform:translateX(-100%)}to{transform:translateX(0)}}`;
    document.head.appendChild(style);
    document.body.appendChild(overlay);
  }

  requestAnimationFrame(() => overlay.style.opacity = "1");
  const node = overlay.querySelector("#sartiq-phrase");
  phrases.forEach((text, index) => setTimeout(() => {
    node.style.opacity = "0";
    setTimeout(() => { node.textContent = text; node.style.opacity = "1"; }, 150);
  }, index * 850));
  node.style.transition = "opacity .25s ease";
  node.textContent = phrases[0];
  setTimeout(() => {
    overlay.style.opacity = "0";
    setTimeout(() => overlay.remove(), 400);
    document.querySelector("#result")?.scrollIntoView({behavior:"smooth", block:"center"});
  }, 3700);

  return gallery;
}
"""

